<?php require_once __DIR__.'/../config.php';require_admin();$pageTitle='Admin dashboard';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['application_id']??0);$status=$_POST['status']??'';$note=trim($_POST['admin_note']??'');if($id>0&&in_array($status,['Pending','Approved','Rejected'],true)){$q=db()->prepare('UPDATE applications SET status=?,admin_note=?,updated_at=NOW() WHERE id=?');$q->execute([$status,$note,$id]);flash('success','Application status updated.');}redirect('admin/dashboard.php');}$filter=$_GET['status']??'';$sql='SELECT a.*,u.email FROM applications a JOIN users u ON a.user_id=u.id';$params=[];if(in_array($filter,['Pending','Approved','Rejected'],true)){$sql.=' WHERE a.status=?';$params[]=$filter;}$sql.=' ORDER BY a.created_at DESC';$q=db()->prepare($sql);$q->execute($params);$apps=$q->fetchAll();$counts=db()->query("SELECT COUNT(*) total,SUM(status='Pending') pending,SUM(status='Approved') approved,SUM(status='Rejected') rejected FROM applications")->fetch();require __DIR__.'/../includes/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Administration</div><h1>Application management</h1><p>Welcome, <?= e(current_user()['name']) ?>. Review and update student applications.</p></div><a class="btn" href="<?= BASE_URL ?>/admin/dashboard.php">Refresh list</a></div><?php show_flash(); ?><div class="stat-grid"><div class="stat"><span>Total applications</span><strong><?= (int)$counts['total'] ?></strong></div><div class="stat"><span>Pending review</span><strong><?= (int)$counts['pending'] ?></strong></div><div class="stat"><span>Approved</span><strong><?= (int)$counts['approved'] ?></strong></div></div><div class="dash-card"><div class="filter-row"><strong style="color:var(--navy);margin-right:auto">Student applications</strong><a class="small-btn" href="?status=">All</a><a class="small-btn" href="?status=Pending">Pending</a><a class="small-btn" href="?status=Approved">Approved</a><a class="small-btn" href="?status=Rejected">Rejected</a></div><?php if(!$apps): ?><div class="empty-state"><strong>No applications found</strong><span>New student submissions will appear here.</span></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>ID / Student</th><th>Programme</th><th>Academic</th><th>Document</th><th>Review application</th></tr></thead><tbody><?php foreach($apps as $a): ?><tr><td><strong>CB-<?= str_pad((string)$a['id'],5,'0',STR_PAD_LEFT) ?></strong><br><?= e($a['full_name']) ?><br><span class="muted"><?= e($a['email']) ?></span></td><td><?= e($a['programme']) ?><br><span class="badge <?= e($a['status']) ?>"><?= e($a['status']) ?></span></td><td><?= e($a['qualification']) ?><br><?= e($a['percentage']) ?>% · <?= e($a['passing_year']) ?></td><td><?php if($a['document']): ?><a href="<?= BASE_URL ?>/admin/document.php?id=<?= (int)$a['id'] ?>" target="_blank">View file</a><?php else: ?>—<?php endif; ?></td><td><form method="post" style="min-width:230px"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="application_id" value="<?= (int)$a['id'] ?>"><select name="status" style="padding:7px;border:1px solid var(--line);margin-bottom:6px;width:100%"><option <?= $a['status']==='Pending'?'selected':'' ?>>Pending</option><option <?= $a['status']==='Approved'?'selected':'' ?>>Approved</option><option <?= $a['status']==='Rejected'?'selected':'' ?>>Rejected</option></select><input name="admin_note" value="<?= e($a['admin_note']) ?>" placeholder="Optional note" style="padding:7px;border:1px solid var(--line);width:100%;margin-bottom:6px"><button class="small-btn">Save update</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><div class="notice">Student records and uploaded documents are for demonstration. Use this portal with test data only.</div></div></section><?php require __DIR__.'/../includes/footer.php';?>
